use std::fs

fn main() {
    let n = 200000
    let mut sieve = []
    let mut cnt = []
    let mut last = []
    let mut c = 0
    let mut l = 0
    for i in 0..(n + 1) {
        sieve.push(true)
    }
    for i in 0..(n + 1) {
        if i >= 2 && sieve[i] {
            c += 1
            l = i
            if i <= 500 {
                let mut j = i * i
                while j <= n {
                    sieve[j] = false
                    j += i
                }
            }
        }
        cnt.push(c)
        last.push(l)
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            continue
        }
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        let v: int = t.parse().unwrap_or(0)
        if cnt[v] == 0 {
            println("0 none")
        } else {
            println("${cnt[v]} ${last[v]}")
        }
    }
}

